            color: "#111827",
            background: "#ffffff"
          },
          x: {
            type: "band",
            domain: colorDomain,
            label: seriesLabel
          },
          y: {
            label: `Total AUC (${aucMetricDescription})`,
            grid: true,
            ...(useAucLogScale ? {type: "log"} : {zero: true}),
            nice: true
          },
          color: {
            legend: true,
            label: seriesLabel,
            domain: colorDomain,
            range: colorRange
          },
          marks: [
            Plot.boxY(aucData, {
              x: "series_id",
              y: "auc_value",
              fill: "series_id",
              fillOpacity: 0.4,
